('01a188d9-1176-7dfb-8980-ad595b4feb36', 'en', 'billing.manageTitle', 'Manage subscription'),
('01a188d9-1177-7a63-8e6a-9b3e29613ddb', 'en', 'billing.manageText', 'Change the plan, update the payment method, see invoices or cancel, on Stripe''s secure portal. A cancelled plan stays paid until the end of its period.'),
('01a188d9-1178-70ed-83ce-3deba1c3bbeb', 'en', 'billing.manage', 'Open billing portal'),
('01a188d9-1179-758c-9a29-aba6464c3266', 'en', 'billing.checkoutDone', 'Payment received. The new plan shows here once Stripe confirms it, usually within seconds.'),
('01a188d9-117a-7817-a9dd-d749eec208e9', 'en', 'billing.adminsOnly', 'Only TenantAdmins can change the subscription.'),
('01a188d9-117b-7fa0-afb1-9e6b8b056935', 'en', 'tenants.tierByBilling', 'Each tenant''s tier follows its subscription (billing), so it cannot be set here.'),
('01a188d9-117c-7a86-85e0-fe50d201c2d5', 'el', 'nav.billing', 'Συνδρομή'),
('01a188d9-117d-74c1-ad53-60986c07dc68', 'el', 'billing.planTitle', 'Τρέχον πακέτο'),
('01a188d9-117e-79e4-9f95-287efe73b6a8', 'el', 'billing.planText', 'Το πακέτο ορίζει τα όρια αιτημάτων του οργανισμού και αλλάζει μαζί με τη συνδρομή.'),
('01a188d9-117f-7513-9770-234350388ae7', 'el', 'billing.none', 'Δεν υπάρχει ακόμη συνδρομή: ο οργανισμός είναι στο δωρεάν πακέτο.'),
('01a188d9-1180-7c10-8430-3f48b3aa886b', 'el', 'billing.renewsOn', 'Ανανεώνεται στις'),
